import{_ as e,c as i,o as r,a as n}from"./app.19f3f8f0.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[{"level":2,"title":"Information we collect","slug":"information-we-collect","link":"#information-we-collect","children":[]},{"level":2,"title":"How we use information","slug":"how-we-use-information","link":"#how-we-use-information","children":[]},{"level":2,"title":"Service providers and sharing","slug":"service-providers-and-sharing","link":"#service-providers-and-sharing","children":[]},{"level":2,"title":"Retention and deletion","slug":"retention-and-deletion","link":"#retention-and-deletion","children":[]},{"level":2,"title":"Your choices and rights","slug":"your-choices-and-rights","link":"#your-choices-and-rights","children":[]},{"level":2,"title":"Cookies, advertising, and transfers","slug":"cookies-advertising-and-transfers","link":"#cookies-advertising-and-transfers","children":[]},{"level":2,"title":"Security and children","slug":"security-and-children","link":"#security-and-children","children":[]},{"level":2,"title":"Changes and contact","slug":"changes-and-contact","link":"#changes-and-contact","children":[]}],"relativePath":"privacy-policy.md"}'),a={name:"privacy-policy.md"},o=n('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-hidden="true">#</a></h1><p><strong>Effective date:</strong> 2026-08-29 · <strong>Last updated:</strong> 2026-08-29</p><p>This Privacy Policy applies to TLDR websites and apps, including services with an app-specific policy page. “TLDR,” “we,” or “us” means the service operator identified on the relevant app or website.</p><h2 id="information-we-collect" tabindex="-1">Information we collect <a class="header-anchor" href="#information-we-collect" aria-hidden="true">#</a></h2><p>Depending on the service and features you use, we may collect:</p><ul><li>Information you provide, such as your email address and support messages.</li><li>Device and technical information, such as IP address, device model, operating-system version, app version, advertising identifiers, crash reports, and logs.</li><li>Usage information, such as interactions, diagnostics, service settings, notification preferences, and notification tokens where enabled.</li><li>Content and records you create or submit, such as photos, videos, prompts, emotion or wellness entries, baby-care logs, game progress, or connected-account content such as comments and messages, only when the relevant feature requires it.</li><li>Purchase or entitlement information, such as product, transaction, or subscription status, where needed for in-app purchases. Payment details are handled by the App Store.</li></ul><p>We collect this information from you, your device, the service you connect, and our service providers.</p><p>Some apps operate mainly or entirely on-device. In those apps, content remains on your device unless you choose to share it with iOS or another service.</p><h2 id="how-we-use-information" tabindex="-1">How we use information <a class="header-anchor" href="#how-we-use-information" aria-hidden="true">#</a></h2><p>We use information to provide and maintain services, process requested features, respond to support requests, diagnose errors, prevent abuse, improve security and performance, measure or deliver advertising where enabled, and comply with law.</p><h2 id="service-providers-and-sharing" tabindex="-1">Service providers and sharing <a class="header-anchor" href="#service-providers-and-sharing" aria-hidden="true">#</a></h2><p>We may disclose information to providers that host, operate, secure, analyze, support, or advertise our services, only for the purposes described here. Depending on the service, this may include Apple and App Store services, Google AdMob, AI or processing providers such as Google Cloud or Vertex AI, email/support providers, crash or analytics providers, and Meta/Instagram APIs for connected-account features. Providers may use information only to deliver their service and must protect it consistently with this policy and applicable requirements. We may also disclose information when required by law or necessary to protect rights, safety, or the service. We do not sell personal information for money.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-hidden="true">#</a></h2><p>We retain each category of information only for as long as needed for its stated purpose, then delete or anonymize it unless a longer period is required by law, dispute resolution, security, or legitimate business records. Support requests are retained for the period needed to resolve and document them.</p><h2 id="your-choices-and-rights" tabindex="-1">Your choices and rights <a class="header-anchor" href="#your-choices-and-rights" aria-hidden="true">#</a></h2><p>Subject to applicable law, you may request access to, correction of, deletion of, or restriction of processing of your personal information, and may object to or withdraw consent for processing based on consent. Email requests to <strong><a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a></strong>. We may verify your identity before responding, will respond within the period required by applicable law, and will explain if a request cannot be fulfilled.</p><h2 id="cookies-advertising-and-transfers" tabindex="-1">Cookies, advertising, and transfers <a class="header-anchor" href="#cookies-advertising-and-transfers" aria-hidden="true">#</a></h2><p>Our website may use essential, analytics, or advertising cookies; see the <a href="/cookie-policy">Cookie Policy</a>. Apps may use advertising identifiers or similar SDK technologies. You can manage available permissions and advertising settings through your browser or device settings. Our providers may process information outside your country, including in South Korea or other countries where they operate; we use safeguards required by applicable law.</p><h2 id="security-and-children" tabindex="-1">Security and children <a class="header-anchor" href="#security-and-children" aria-hidden="true">#</a></h2><p>We use reasonable technical and organizational safeguards, including access controls and least-privilege practices. Our services are not directed to children under 13, and we do not knowingly collect their personal information. Contact us if you believe a child has provided information.</p><h2 id="changes-and-contact" tabindex="-1">Changes and contact <a class="header-anchor" href="#changes-and-contact" aria-hidden="true">#</a></h2><p>We may update this policy by posting a revised version with a new date. Questions or privacy requests: <strong><a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a></strong>.</p>',22),t=[o];function s(c,d,l,h,p,u){return r(),i("div",null,t)}const v=e(a,[["render",s]]);export{y as __pageData,v as default};
